def analyze_complexity_tier(step_count):
    ratio = step_count(2000) / step_count(1000)
    if ratio < 1.5:
        return 'O(1)'
    if ratio < 3.0:
        return 'O(N)'
    return 'O(N^2)'

def get_dominant_term(terms):
    order = ['O(1)', 'O(log N)', 'O(N)', 'O(N log N)', 'O(N^2)', 'O(2^N)']
    return max(terms, key=order.index)

class DynamicArray:
    def __init__(self, capacity=2):
        self._capacity = capacity
        self._size = 0
        self._data = [None] * capacity

    def push(self, value):
        if self._size == self._capacity:
            self._capacity *= 2
            new_data = [None] * self._capacity
            for i in range(self._size):
                new_data[i] = self._data[i]
            self._data = new_data
        self._data[self._size] = value
        self._size += 1

    def get(self, index):
        return self._data[index]

    def size(self):
        return self._size

    def capacity(self):
        return self._capacity

