class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

from collections import OrderedDict


def run_lru_operations(capacity, ops):
    cache = OrderedDict()
    results = []
    for op in ops:
        if op[0] == 'put':
            _, k, v = op
            if k in cache:
                cache.move_to_end(k)
            cache[k] = v
            if len(cache) > capacity:
                cache.popitem(last=False)
        else:
            _, k = op
            if k not in cache:
                results.append(-1)
            else:
                cache.move_to_end(k)
                results.append(cache[k])
    return results

class CircularQueue:
    def __init__(self, k):
        self.data = [None] * k
        self.k = k
        self.head = 0
        self.count = 0

    def en_queue(self, value):
        if self.is_full():
            return False
        tail = (self.head + self.count) % self.k
        self.data[tail] = value
        self.count += 1
        return True

    def de_queue(self):
        if self.is_empty():
            return False
        self.head = (self.head + 1) % self.k
        self.count -= 1
        return True

    def front(self):
        return -1 if self.is_empty() else self.data[self.head]

    def rear(self):
        if self.is_empty():
            return -1
        return self.data[(self.head + self.count - 1) % self.k]

    def is_empty(self):
        return self.count == 0

    def is_full(self):
        return self.count == self.k

