def merge_two_lists(l1, l2):
    dummy = ListNode()
    tail = dummy
    while l1 and l2:
        if l1.val <= l2.val:
            tail.next = l1
            l1 = l1.next
        else:
            tail.next = l2
            l2 = l2.next
        tail = tail.next
    tail.next = l1 or l2
    return dummy.next

def find_kth_largest(nums, k):
    arr = nums[:]
    target = len(arr) - k

    def partition(lo, hi):
        pivot = arr[hi]
        p = lo
        for i in range(lo, hi):
            if arr[i] <= pivot:
                arr[p], arr[i] = arr[i], arr[p]
                p += 1
        arr[p], arr[hi] = arr[hi], arr[p]
        return p

    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        p = partition(lo, hi)
        if p == target:
            return arr[p]
        if p < target:
            lo = p + 1
        else:
            hi = p - 1

def quick_sort(arr, lo=0, hi=None):
    if hi is None:
        hi = len(arr) - 1
    if lo >= hi:
        return arr
    pivot = arr[hi]
    p = lo
    for i in range(lo, hi):
        if arr[i] <= pivot:
            arr[p], arr[i] = arr[i], arr[p]
            p += 1
    arr[p], arr[hi] = arr[hi], arr[p]
    quick_sort(arr, lo, p - 1)
    quick_sort(arr, p + 1, hi)
    return arr

def sort_colors(nums):
    low, mid, high = 0, 0, len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1

def counting_sort(arr, max_val):
    counts = [0] * (max_val + 1)
    for v in arr:
        counts[v] += 1
    out = []
    for v in range(max_val + 1):
        out.extend([v] * counts[v])
    return out

