def lowest_common_ancestor(root, p, q):
    node = root
    while node:
        if p < node.val and q < node.val:
            node = node.left
        elif p > node.val and q > node.val:
            node = node.right
        else:
            return node

class MinHeap:
    def __init__(self):
        self.data = []

    def push(self, val):
        self.data.append(val)
        i = len(self.data) - 1
        while i > 0:
            p = (i - 1) // 2
            if self.data[i] < self.data[p]:
                self.data[i], self.data[p] = self.data[p], self.data[i]
                i = p
            else:
                break

    def pop(self):
        top = self.data[0]
        last = self.data.pop()
        if self.data:
            self.data[0] = last
            i = 0
            n = len(self.data)
            while True:
                l, r = 2 * i + 1, 2 * i + 2
                smallest = i
                if l < n and self.data[l] < self.data[smallest]:
                    smallest = l
                if r < n and self.data[r] < self.data[smallest]:
                    smallest = r
                if smallest == i:
                    break
                self.data[i], self.data[smallest] = self.data[smallest], self.data[i]
                i = smallest
        return top

    def peek(self):
        return self.data[0]

    def size(self):
        return len(self.data)

