def find_words_with_prefix(trie, prefix):
    node = trie.root
    for ch in prefix:
        if ch not in node.children:
            return []
        node = node.children[ch]
    words = []

    def collect(curr, text):
        if curr.is_end:
            words.append(text)
        for ch, child in curr.children.items():
            collect(child, text + ch)

    collect(node, prefix)
    return words

from collections import deque


def shortest_path_bfs(graph, start, target):
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        node, dist = queue.popleft()
        if node == target:
            return dist
        for nb in graph.get(node, []):
            if nb not in visited:
                visited.add(nb)
                queue.append((nb, dist + 1))
    return -1

def count_components(n, edges):
    neighbours = [[] for _ in range(n)]
    for a, b in edges:
        neighbours[a].append(b)
        neighbours[b].append(a)
    seen = [False] * n
    count = 0
    for i in range(n):
        if not seen[i]:
            count += 1
            stack = [i]
            seen[i] = True
            while stack:
                u = stack.pop()
                for v in neighbours[u]:
                    if not seen[v]:
                        seen[v] = True
                        stack.append(v)
    return count

class AutocompleteSystem:
    def __init__(self):
        self.freq = {}

    def insert(self, word, freq):
        self.freq[word] = self.freq.get(word, 0) + freq

    def suggest(self, prefix, k=3):
        matches = [w for w in self.freq if w.startswith(prefix)]
        matches.sort(key=lambda w: (-self.freq[w], w))
        return matches[:k]

import heapq


def dijkstra(graph, start):
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist[node]:
            continue
        for nb, w in graph.get(node, []):
            nd = d + w
            if nd < dist.get(nb, float('inf')):
                dist[nb] = nd
                heapq.heappush(heap, (nd, nb))
    return dist

import heapq


def network_delay_time(times, n, k):
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in times:
        graph[u].append((v, w))
    dist = {k: 0}
    heap = [(0, k)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist[node]:
            continue
        for nb, w in graph[node]:
            nd = d + w
            if nd < dist.get(nb, float('inf')):
                dist[nb] = nd
                heapq.heappush(heap, (nd, nb))
    return max(dist.values()) if len(dist) == n else -1

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1
        return True

    def connected(self, x, y):
        return self.find(x) == self.find(y)

def find_redundant_connection(edges):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return [a, b]
        parent[ra] = rb

def rob(nums):
    prev, curr = 0, 0
    for x in nums:
        prev, curr = curr, max(curr, prev + x)
    return curr

def climb_stairs(n):
    a, b = 1, 1
    for _ in range(n - 1):
