def hamming_weight(n):
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count

def find_cheapest_flight(n, flights, src, dst, k):
    cost = [float('inf')] * n
    cost[src] = 0
    for _ in range(k + 1):
        nxt = cost[:]
        for u, v, p in flights:
            if cost[u] + p < nxt[v]:
                nxt[v] = cost[u] + p
        cost = nxt
    return -1 if cost[dst] == float('inf') else cost[dst]

def audit_flight_graph(flights):
    airports = {a for f in flights for a in f[:2]}
    cheapest = min((f[2] for f in flights), default=None)
    return {'routes': len(flights), 'airports': len(airports), 'cheapest': cheapest}
